    try {
        const ec2Client = new EC2Client({ region });
        const response = await ec2Client.send(new CreateTagsCommand({ Resources: instanceIds, Tags: tags }));
        return response;
    } catch (err) {
        console.log('Error', err);
        throw new Error(err);
