const {IAMClient,CreateRoleCommand,PutRolePolicyCommand,DeleteRolePolicyCommand,DeleteRoleCommand}=require('@aws-sdk/client-iam');
const iam=new IAMClient({});
const trust=(extId)=>JSON.stringify({Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{AWS:'arn:aws:iam::600000000042:root'},Action:'sts:AssumeRole',...(extId?{Condition:{StringEquals:{'sts:ExternalId':extId}}}:{})}]});
const ec2Policy=JSON.stringify({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['ec2:Describe*'],Resource:'*'}]});
const s3Policy=JSON.stringify({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:*'],Resource:'*'}]});
(async()=>{
  const roles=[
    {name:'verify-scraper-ok',extId:'ext-123',policy:ec2Policy},
    {name:'verify-scraper-noec2',extId:'ext-123',policy:s3Policy},
  ];
  for (const r of roles){
    try{await iam.send(new CreateRoleCommand({RoleName:r.name,AssumeRolePolicyDocument:trust(r.extId)}));}catch(e){console.log('exists?',r.name,e.name);}
    await iam.send(new PutRolePolicyCommand({RoleName:r.name,PolicyName:'p',PolicyDocument:r.policy}));
    console.log('ready',r.name);
  }
})();
EOF
