import { validateCloudIAM } from './cloudIAMAuthorizer.js';
import { BadRequestException } from '@nestjs/common';

const OK = 'arn:aws:iam::600000000042:role/verify-scraper-ok';
const NOEC2 = 'arn:aws:iam::600000000042:role/verify-scraper-noec2';

describe('live cloudIAM validation against the local AWS emulator', () => {
    it('accepts an assumable role that can read the instance inventory', async () => {
        await expect(validateCloudIAM({ iamRoleArn: OK, externalId: 'ext-123' })).resolves.toEqual({
            iamRoleArn: OK,
            externalId: 'ext-123',
        });
    });
    it('rejects when the external id is wrong', async () => {
        await expect(validateCloudIAM({ iamRoleArn: OK, externalId: 'nope' })).rejects.toBeInstanceOf(
            BadRequestException,
        );
        await expect(validateCloudIAM({ iamRoleArn: OK })).rejects.toThrow(/IAM/);
    });
    it('rejects when the role cannot read the instance inventory', async () => {
        await expect(validateCloudIAM({ iamRoleArn: NOEC2, externalId: 'ext-123' })).rejects.toThrow(/inventory/);
    });
    it('rejects a nonexistent / garbage role', async () => {
        await expect(validateCloudIAM({ iamRoleArn: 'wow a fake role' })).rejects.toThrow(/IAM/);
        await expect(
            validateCloudIAM({ iamRoleArn: 'arn:aws:iam::600000000042:role/does-not-exist' }),
        ).rejects.toThrow(/IAM/);
    });
    it('treats a blank role as a disconnect clearing the external id', async () => {
        await expect(validateCloudIAM({ iamRoleArn: '', externalId: 'ext-123' })).resolves.toEqual({
            iamRoleArn: '',
            externalId: '',
        });
    });
    it('treats a block naming no role as invalid', async () => {
        await expect(validateCloudIAM({} as never)).rejects.toThrow(/iamRoleArn/);
        await expect(validateCloudIAM({ externalId: 'ext-123' })).rejects.toBeInstanceOf(BadRequestException);
    });
    it('exposes the failure as an array message like class-validator does', async () => {
        try {
            await validateCloudIAM({ iamRoleArn: NOEC2, externalId: 'ext-123' });
            throw new Error('should have thrown');
        } catch (e) {
            expect(e.getStatus()).toEqual(400);
            const response = e.getResponse();
            expect(Array.isArray(response.message)).toEqual(true);
            expect(response.message[0]).toEqual(expect.stringContaining('IAM'));
        }
    });
});
EOF
