cat <<'EOF' > /app/src/setting/liveSettingsUpdate.spec.ts
import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { BadRequestException } from '@nestjs/common';
import { validate } from 'class-validator';
import { plainToInstance } from 'class-transformer';
import { SettingsService } from './settings.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';

const OK = 'arn:aws:iam::600000000042:role/verify-scraper-ok';
const NOEC2 = 'arn:aws:iam::600000000042:role/verify-scraper-noec2';

describe('settings update with scraper role', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
    });
    afterEach(() => jest.clearAllMocks());

    it('saves a good role', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const { data } = await service.update({
            businessID: 'b',
            subject: 's',
            cloudIAM: { iamRoleArn: OK, externalId: 'ext-123' },
        });
        expect(influxService.loadPoints).toBeCalledTimes(1);
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: OK, externalId: 'ext-123' });
    });

    it('does not write anything when the role cannot be assumed', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            service.update({ businessID: 'b', subject: 's', cloudIAM: { iamRoleArn: OK, externalId: 'wrong' } }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('does not write anything when the role cannot read the inventory', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            service.update({ businessID: 'b', subject: 's', cloudIAM: { iamRoleArn: NOEC2, externalId: 'ext-123' } }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('clears the external id on disconnect', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const { data } = await service.update({
            businessID: 'b',
            subject: 's',
            cloudIAM: { iamRoleArn: '', externalId: 'ext-123' },
        });
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
    });

    it('rejects a settings block naming no role', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            service.update({ businessID: 'b', subject: 's', cloudIAM: { externalId: 'ext-123' } }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('other settings still save without a cloudIAM block', async () => {
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const res = await service.update({ businessID: 'b', subject: 's', businessName: 'foo' });
        expect(res.message).toEqual('Setting updated successfully');
        expect(influxService.loadPoints).toBeCalledTimes(1);
    });

    describe('dto validation', () => {
        it('fails validation for a role that cannot be assumed', async () => {
            const dto = plainToInstance(UpdateSettingsDto, { cloudIAM: { iamRoleArn: OK, externalId: 'bad' } });
            const errors = await validate(dto);
            expect(errors.length).toBeGreaterThan(0);
            expect(JSON.stringify(errors)).toEqual(expect.stringContaining('IAM'));
        });
        it('passes validation for a good role and for a disconnect', async () => {
            expect(
                await validate(
                    plainToInstance(UpdateSettingsDto, { cloudIAM: { iamRoleArn: OK, externalId: 'ext-123' } }),
                ),
            ).toEqual([]);
            expect(
                await validate(plainToInstance(UpdateSettingsDto, { cloudIAM: { iamRoleArn: '', externalId: 'x' } })),
            ).toEqual([]);
        });
        it('fails validation when no role is named', async () => {
            const errors = await validate(plainToInstance(UpdateSettingsDto, { cloudIAM: { externalId: 'x' } }));
            expect(errors.length).toBeGreaterThan(0);
        });
    });
});
EOF
