import { BadRequestException } from '@nestjs/common';

const assumeRoleMock = jest.fn();
const getInstanceWithFiltersMock = jest.fn();

jest.mock('@aws-sdk/credential-providers', () => ({
    fromTemporaryCredentials: (input) => () => assumeRoleMock(input),
}));

jest.mock('../../utils/aws/awsEc2', () => ({
    getInstanceWithFilters: (...args) => getInstanceWithFiltersMock(...args),
}));

import {
    CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE,
    CLOUD_IAM_INVALID_BLOCK_MESSAGE,
    CLOUD_IAM_INVENTORY_FAILURE_MESSAGE,
    isCloudIAMDisconnect,
    validateCloudIAM,
    ValidCloudIAMRule,
} from './cloudIAMAuthorizer.js';

const credentials = { accessKeyId: 'a', secretAccessKey: 'b', sessionToken: 'c' };
const iamRoleArn = 'arn:aws:iam::[REDACTED_AWS_ACCOUNT_ID]:role/meteringco-scraper';

describe('cloudIAM (scraper role) validation', () => {
    beforeEach(() => {
        assumeRoleMock.mockReset();
        getInstanceWithFiltersMock.mockReset();
        assumeRoleMock.mockResolvedValue(credentials);
        getInstanceWithFiltersMock.mockResolvedValue([]);
    });

    it('proves the role can be assumed with the external id supplied and reads the instance inventory', async () => {
        const result = await validateCloudIAM({ iamRoleArn, externalId: 'externally-unique' });

        expect(result).toEqual({ iamRoleArn, externalId: 'externally-unique' });
        expect(assumeRoleMock).toBeCalledTimes(1);
        expect(assumeRoleMock.mock.calls[0][0].params).toEqual(
            expect.objectContaining({ RoleArn: iamRoleArn, ExternalId: 'externally-unique' }),
        );
        expect(getInstanceWithFiltersMock).toBeCalledTimes(1);
        expect(getInstanceWithFiltersMock.mock.calls[0][1]).toEqual(credentials);
    });

    it('is a bad request when the role cannot be assumed', async () => {
        assumeRoleMock.mockRejectedValueOnce(new Error('AccessDenied'));

        await expect(validateCloudIAM({ iamRoleArn, externalId: 'nope' })).rejects.toBeInstanceOf(BadRequestException);
        await expect(validateCloudIAM({ iamRoleArn, externalId: 'nope' })).resolves.toBeTruthy();
        expect(getInstanceWithFiltersMock).toBeCalledTimes(1);
    });

    it('is a bad request when the assumed credentials cannot read the instance inventory', async () => {
        getInstanceWithFiltersMock.mockRejectedValueOnce(new BadRequestException('Invalid IAM role or external ID'));

        await expect(validateCloudIAM({ iamRoleArn })).rejects.toThrow(CLOUD_IAM_INVENTORY_FAILURE_MESSAGE);
    });

    it('treats a blank role as a disconnect and clears the external id without calling AWS', async () => {
        await expect(validateCloudIAM({ iamRoleArn: '', externalId: 'externally-unique' })).resolves.toEqual({
            iamRoleArn: '',
            externalId: '',
        });
        expect(isCloudIAMDisconnect({ iamRoleArn: '' })).toEqual(true);
        expect(assumeRoleMock).not.toBeCalled();
        expect(getInstanceWithFiltersMock).not.toBeCalled();
    });

    it('treats a settings block which names no role as invalid rather than a disconnect', async () => {
        await expect(validateCloudIAM({ externalId: 'externally-unique' })).rejects.toThrow(
            CLOUD_IAM_INVALID_BLOCK_MESSAGE,
        );
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        await expect(validateCloudIAM({ iamRoleArn: null })).rejects.toThrow(CLOUD_IAM_INVALID_BLOCK_MESSAGE);
        expect(isCloudIAMDisconnect({ externalId: 'externally-unique' })).toEqual(false);
        expect(assumeRoleMock).not.toBeCalled();
    });

    it('reports the failure as an array of messages, like the other settings validations do', async () => {
        assumeRoleMock.mockRejectedValueOnce(new Error('AccessDenied'));
        let thrown;
        try {
            await validateCloudIAM({ iamRoleArn });
        } catch (e) {
            thrown = e;
        }
        expect(thrown.getStatus()).toEqual(400);
        expect(thrown.getResponse().message).toEqual([CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE]);
        expect(thrown.message).toEqual(CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE);
    });

    describe('ValidCloudIAMRule', () => {
        const rule = new ValidCloudIAMRule();

        it('passes when no cloudIAM block was sent in', async () => {
            await expect(rule.validate(undefined, { object: {} } as never)).resolves.toEqual(true);
            expect(assumeRoleMock).not.toBeCalled();
        });

        it('passes for a usable scraper role', async () => {
            await expect(rule.validate({ iamRoleArn }, { object: {} } as never)).resolves.toEqual(true);
        });

        it('fails, with a message mentioning the IAM role, for an unusable scraper role', async () => {
            assumeRoleMock.mockRejectedValueOnce(new Error('AccessDenied'));
            const args = { object: { cloudIAM: { iamRoleArn } } } as never;

            await expect(rule.validate({ iamRoleArn }, args)).resolves.toEqual(false);
            expect(rule.defaultMessage(args)).toEqual(CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE);
            expect(rule.defaultMessage(args)).toEqual(expect.stringContaining('IAM'));
        });
    });
});
EOF
