import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { serializeError } from 'serialize-error';
import { getInstanceWithFilters } from '../../utils/aws/awsEc2.js';

/**
 * The shape of the cloud IAM (scraper role) settings block sent in by a customer.
 * Kept as a structural type to avoid a circular runtime dependency with the settings DTO.
 */
export interface CloudIAMLike {
    iamRoleArn?: string;
    externalId?: string;
}

/**
 * The session name used when MeteringCo proves that the customer supplied scraper role can be assumed.
 */
export const SCRAPER_ROLE_VALIDATION_SESSION_NAME = 'meteringcoScraperRoleValidation';

/**
 * The default region used when validating the scraper role, this mirrors the region used by the
 * collection (data gathering) micro services.
 */
export const SCRAPER_ROLE_VALIDATION_REGION = 'us-east-1';

export const CLOUD_IAM_INVALID_BLOCK_MESSAGE =
    'cloudIAM: An IAM role (cloudIAM.iamRoleArn) must be provided. Send an empty iamRoleArn to disconnect the IAM role';

export const CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE =
    'cloudIAM: MeteringCo is unable to assume the IAM role provided with the external ID supplied. Please double check the IAM role ARN, its trust policy and the external ID';

export const CLOUD_IAM_INVENTORY_FAILURE_MESSAGE =
    'cloudIAM: The IAM role provided was assumed but it is not allowed to read the EC2 instance inventory (ec2:DescribeInstances) used to collect usage. Please double check the permissions attached to the IAM role';

/**
 * A Bad Request raised when a customer supplied scraper role (cloudIAM) cannot be used by MeteringCo.
 * The response body keeps the same shape as the class-validator driven errors (an array of messages)
 * while the error message itself stays human readable.
 */
export class CloudIAMValidationException extends BadRequestException {
    constructor(message: string) {
        super([message], 'Bad Request');
        this.message = message;
    }
}

/**
 * A cloudIAM block with a blank role means the customer wants to disconnect their AWS account.
 */
export const isCloudIAMDisconnect = (cloudIAM?: CloudIAMLike): boolean =>
    typeof cloudIAM?.iamRoleArn === 'string' && cloudIAM.iamRoleArn.trim() === '';

/**
 * The cloudIAM block persisted when a customer disconnects, the external ID must be cleared along
 * with the role so a stale external ID is never kept around.
 */
export const disconnectedCloudIAM = (): CloudIAMLike => ({ iamRoleArn: '', externalId: '' });

/**
 * Proves the customer supplied scraper role can be assumed by MeteringCo with the external ID supplied.
 * Returns the temporary credentials handed back by STS.
 */
export const assumeScraperRole = async (
    { iamRoleArn, externalId }: CloudIAMLike,
    region: string = SCRAPER_ROLE_VALIDATION_REGION,
) => {
    const credentialProvider = fromTemporaryCredentials({
        params: {
            RoleArn: iamRoleArn,
            ExternalId: externalId ? externalId : undefined,
            RoleSessionName: SCRAPER_ROLE_VALIDATION_SESSION_NAME,
        },
        clientConfig: { region },
    });
    // Resolving the provider performs the sts:AssumeRole call, proving the role can be assumed.
    return credentialProvider();
};

/**
 * Validates a customer supplied scraper role (cloudIAM) settings block.
 *
 * - A blank `iamRoleArn` is a disconnect, the external ID is cleared and no AWS calls are made.
 * - A block which does not name a role at all is invalid, it is not treated as a disconnect.
 * - Otherwise the role must be assumable with the external ID supplied and the returned credentials
 *   must be able to read the EC2 instance inventory used by collection.
 *
 * @throws CloudIAMValidationException (a BadRequestException) when any of the checks above fail.
 * @returns the cloudIAM block which should be persisted.
 */
export const validateCloudIAM = async (
    cloudIAM: CloudIAMLike,
    region: string = SCRAPER_ROLE_VALIDATION_REGION,
): Promise<CloudIAMLike> => {
    const logger = new Logger('CloudIAMValidation');
    if (!cloudIAM || typeof cloudIAM !== 'object' || Array.isArray(cloudIAM)) {
        throw new CloudIAMValidationException(CLOUD_IAM_INVALID_BLOCK_MESSAGE);
    }
    const { iamRoleArn, externalId } = cloudIAM;

    if (typeof iamRoleArn !== 'string') {
        // A settings block which names no role is invalid, it is not a disconnect request.
        throw new CloudIAMValidationException(CLOUD_IAM_INVALID_BLOCK_MESSAGE);
    }

    if (iamRoleArn.trim() === '') {
        // Disconnecting, the external ID must be cleared along with the role.
        return disconnectedCloudIAM();
    }

    const trimmedRoleArn = iamRoleArn.trim();
    let credentials;
    try {
        credentials = await assumeScraperRole({ iamRoleArn: trimmedRoleArn, externalId }, region);
    } catch (e) {
        logger.error(
            `Unable to assume the IAM role ${trimmedRoleArn} with the external ID supplied: ${JSON.stringify(
                serializeError(e),
            )}`,
        );
        throw new CloudIAMValidationException(CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE);
    }

    try {
        // The same inventory read collection relies on, this proves the role is allowed to gather usage.
        await getInstanceWithFilters(region, credentials, []);
    } catch (e) {
        logger.error(
            `The IAM role ${trimmedRoleArn} cannot read the EC2 instance inventory: ${JSON.stringify(
                serializeError(e),
            )}`,
        );
        throw new CloudIAMValidationException(CLOUD_IAM_INVENTORY_FAILURE_MESSAGE);
    }

    return { iamRoleArn: trimmedRoleArn, externalId };
};

@ValidatorConstraint({ name: 'ValidCloudIAMRule', async: true })
@Injectable()
export class ValidCloudIAMRule implements ValidatorConstraintInterface {
    private readonly failures = new WeakMap<object, string>();

    async validate(cloudIAM: CloudIAMLike, args: ValidationArguments) {
        if (cloudIAM === undefined || cloudIAM === null) {
            // Nothing sent in for the scraper role, nothing to check.
            return true;
        }
        try {
            await validateCloudIAM(cloudIAM);
            return true;
        } catch (e) {
            if (args?.object) {
                this.failures.set(args.object, e?.message ?? CLOUD_IAM_INVALID_BLOCK_MESSAGE);
            }
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return (args?.object && this.failures.get(args.object)) || CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE;
    }
}

export function ValidCloudIAM(property?: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidCloudIAM',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidCloudIAMRule,
        });
    };
}
"
}

